const item = $input.item;
const raw = item.json.text; 

let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error(`Invalid JSON from Groq for item: ${String(raw).slice(0, 500)}`);
}

const s = parsed.scores || {};
const r = parsed.rationales || {};

if (!parsed.scores || !parsed.rationales) {
  throw new Error('Groq response missing scores or rationales');
}

// Ensure scores are treated as numbers
const total = (Number(s.process_thinking) || 0) + 
              (Number(s.practical_automation) || 0) +
              (Number(s.clarity_communication) || 0) + 
              (Number(s.execution_logic) || 0) +
              (Number(s.reliability_awareness) || 0);

let outcome = 'Reject';
if (total >= 20) outcome = 'Advance';
else if (total >= 15) outcome = 'Review';

const prev = $('Build Scoring Request').item;

return {
  candidateId: prev.json.candidateId,
  candidateName: prev.json.candidateName,
  scores: s,
  rationales: r,
  total,
  outcome
};

const ctx = $input.first().json;

let f = {};
try {
  f = $('Airtable Trigger').first().json.fields || {};
} catch (e) {
  f = {}; 
}

const systemPrompt = [
  "You generate exactly ONE short sentence (10-25 words) to be inserted into a hiring email.",
  "You MUST write in the SECOND PERSON (using 'you', 'your').", // New Rule
  "DO NOT mention the candidate's name in the sentence.", // New Rule
  "Follow the rules for the given outcome strictly.",
  "",
  "For Advance: Reference the strongest specific element of the candidate's answers. Be warm and specific.",
  "For Review: Be neutral and brief. Acknowledge their effort. NEVER hint they are borderline.",
  "For Reject: Be neutral, brief, and encouraging. NEVER give reasons for rejection. NEVER reference weaknesses.",
  "",
  "Return only the sentence. No quotes, no prose around it, no preamble."
].join("\n");

const rationalesSummary = Object.entries(ctx.rationales || {})
  .map(([key, val]) => `${key.replace('_', ' ')}: ${val}`)
  .join("\n");

const userPrompt = [
  `Outcome: ${ctx.outcome}`,
  `Candidate name: ${ctx.candidateName}`,
  "",
  "--- EVALUATION RATIONALES ---",
  rationalesSummary,
  "",
  "--- RAW ANSWERS ---",
  `Past experience: ${f['Past Experience'] || "N/A"}`,
  `AI usage example: ${f['AI Usage Example'] || "N/A"}`,
  `Q1 answer: ${f['Q1 Answer'] || "N/A"}`,
  "",
  "Generate the one sentence now."
].join("\n");

return {
  ...ctx,
  chatInput: `${systemPrompt}\n\n${userPrompt}`
};

const line = $input.first().json.text.trim();

const prev = $('Build Line Request').first().json;

return {
  candidateId: prev.candidateId,
  candidateName: prev.candidateName,
  scores: prev.scores,
  rationales: prev.rationales,
  total: prev.total,
  outcome: prev.outcome,
  personalizedLine: line
};

const tpl = $input.first().json;

const ctx = $('Extract Line').first().json;

const subject = tpl.Subject || '';
const body = (tpl.Body || '')
  .replace('{{name}}', ctx.candidateName)
  .replace('{{personalized_line}}', ctx.personalizedLine);

return {
  ...ctx,
  subject,
  body
};
